import{_ as p,a0 as o,w as r,s as d,ao as t,I as l,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在無響應的 Linux 系統中殺掉內存消耗最大的進程 | LCTT x X-CMD","titleTemplate":false,"description":"如何在無響應的 Linux 系統中殺掉內存消耗最大的進程 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在無響應的 Linux 系統中殺掉內存消耗最大的進程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在無響應的 Linux 系統中殺掉內存消耗最大的進程 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20171121 How To Kill The Largest Process In An Unresponsive Linux System","title":"如何在無響應的 Linux 系統中殺掉內存消耗最大的進程","tag":"201805","desc":""},"relativePath":"201805/20171121 How To Kill The Largest Process In An Unresponsive Linux System.md","filePath":"[post].md"}'),h={name:"201805/20171121 How To Kill The Largest Process In An Unresponsive Linux System.md"};function g(u,s,k,m,c,b){const e=o("Link");return r(),d("div",null,[s[22]||(s[22]=t(`<h1 id="如何在無響應的-linux-系統中殺掉內存消耗最大的進程" tabindex="-1">如何在無響應的 Linux 系統中殺掉內存消耗最大的進程 <a class="header-anchor" href="#如何在無響應的-linux-系統中殺掉內存消耗最大的進程" aria-label="Permalink to “如何在無響應的 Linux 系統中殺掉內存消耗最大的進程”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/11/Kill-The-Largest-Process-720x340.png" alt=""></p><p>作為一名Blog作者，我收藏了很多Blog、網站和論壇用來尋找 Linux 和 Unix 相關的內容。有時候，我在瀏覽器中開啓了非常多的標籤頁，導致操作系統會無響應好幾分鐘。我不能移動我的鼠標，也不能殺掉一個進程或關閉任何開啓的標籤頁。在這種情況下，我別無選擇，只能強制重啓系統。當然我也用了 <strong>OneTab</strong> （LCTT 譯註：OneTab 是一個 Chrome 的 Extension，可以將標籤頁轉化成一個列表保存。）和 <strong>Greate Suspender</strong> （LCTT 譯註：Great Suspender 是一個 Chrome 的 Extension， 可以自動凍結標籤頁）這樣瀏覽器拓展，但它們在這裏也起不到太大的作用。 我經常耗盡我的內存。而這就是 <strong>Early OOM</strong> 起作用的時候了。在情況嚴重時，它會殺掉一個未響應系統中的內存消耗最大的進程。Early OOM 每秒會檢測可用內存和空餘交換區 10 次，一旦兩者都低於 10%，它就會把最大的進程殺死。</p><h3 id="為什麼用-early-oom-為什麼不用系統內置的-oom-killer" tabindex="-1">為什麼用 Early OOM？為什麼不用系統內置的 OOM killer？ <a class="header-anchor" href="#為什麼用-early-oom-為什麼不用系統內置的-oom-killer" aria-label="Permalink to “為什麼用 Early OOM？為什麼不用系統內置的 OOM killer？”">​</a></h3><p>在繼續討論下去之前，我想先簡短的介紹下 OOM killer，也就是 <strong>O</strong>ut <strong>O</strong>f <strong>M</strong>emory killer。OOM killer 是一個由內核在可用內存非常低的時候使用的進程。它的主要任務是不斷的殺死進程，直到釋放出足夠的內存，使內核正在運行的其它進程能順利運行。OOM killer 會找到系統中最不重要並且能釋放出最多內存的進程，然後殺掉他們。在 <code>/proc</code> 目錄下的 <code>pid</code> 目錄中，我們可以看到每個進程的 <code>oom_score</code>。</p><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/10299/oom_score</span></span>
<span class="line"><span>1</span></span></code></pre></div><p>一個進程的 <code>oom_score</code> 的值越高，這個進程越有可能在系統內存耗盡的時候被 OOM killer 殺死。</p><p>Early OOM 的開發者表示，相對於內置的 OOM killer，Early OOM 有一個很大的優點。就像我之前説的那樣，OOM killer 會殺掉 <code>oom_score</code> 最高的進程，而這也導致 Chrome 瀏覽器總是會成為第一個被殺死的進程。為了避免這種情況發生，Early OOM 使用 <code>/proc/*/status</code> 而不是 <code>echo f &gt; /proc/sysrq-trigger</code>（LCTT 譯註：這條命令會調用 OOM killer 殺死進程）。開發者還表示，手動觸發 OOM killer 在最新版本的 Linux 內核中很可能不會起作用。</p><h3 id="安裝-early-oom" tabindex="-1">安裝 Early OOM <a class="header-anchor" href="#安裝-early-oom" aria-label="Permalink to “安裝 Early OOM”">​</a></h3><p>Early OOM 在 AUR（Arch User Repository）中可以找到，所以你可以在 Arch 和它的衍生版本中使用任何 AUR 工具安裝它。</p>`,11)),l("p",null,[s[1]||(s[1]=a("使用 ",-1)),n(e,{href:"https://www.ostechnix.com/install-pacaur-arch-linux/"},{default:i(()=>[...s[0]||(s[0]=[a("Pacaur",-1)])]),_:1}),s[2]||(s[2]=a("：",-1))]),s[23]||(s[23]=t('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacaur -S earlyoom</span></span></code></pre></div>',1)),l("p",null,[s[4]||(s[4]=a("使用 ",-1)),n(e,{href:"https://www.ostechnix.com/install-packer-arch-linux-2/"},{default:i(()=>[...s[3]||(s[3]=[a("Packer",-1)])]),_:1}),s[5]||(s[5]=a("：",-1))]),s[24]||(s[24]=t('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>packer -S earlyoom</span></span></code></pre></div>',1)),l("p",null,[s[7]||(s[7]=a("使用 ",-1)),n(e,{href:"https://www.ostechnix.com/install-yaourt-arch-linux/"},{default:i(()=>[...s[6]||(s[6]=[a("Yaourt",-1)])]),_:1}),s[8]||(s[8]=a("：",-1))]),s[25]||(s[25]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yaourt -S earlyoom</span></span></code></pre></div><p>啓用並啓動 Early OOM 守護進程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable earlyoom</span></span>
<span class="line"><span>sudo systemctl start earlyoom</span></span></code></pre></div><p>在其它的 Linux 發行版中，可以按如下方法編譯安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/rfjakob/earlyoom.git</span></span>
<span class="line"><span>cd earlyoom</span></span>
<span class="line"><span>make</span></span>
<span class="line"><span>sudo make install</span></span></code></pre></div><h3 id="early-oom-殺掉無響應-linux-系統中的最大的進程" tabindex="-1">Early OOM - 殺掉無響應 Linux 系統中的最大的進程 <a class="header-anchor" href="#early-oom-殺掉無響應-linux-系統中的最大的進程" aria-label="Permalink to “Early OOM - 殺掉無響應 Linux 系統中的最大的進程”">​</a></h3><p>運行如下命令啓動 Early OOM：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>earlyoom</span></span></code></pre></div><p>如果是通過編譯源代碼安裝的， 運行如下命令啓動 Early OOM：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./earlyoom</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>earlyoom 0.12</span></span>
<span class="line"><span>mem total: 3863 MiB, min: 386 MiB (10 %)</span></span>
<span class="line"><span>swap total: 2047 MiB, min: 204 MiB (10 %)</span></span>
<span class="line"><span>mem avail: 1770 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1773 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1772 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1773 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1772 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1773 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1771 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1773 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1784 MiB (46 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>就像你在上面的輸出中可以看到的，Early OOM 將會顯示你有多少內存和交換區，以及有多少可用的內存和交換區。記住它會一直保持運行，直到你按下 <code>CTRL+C</code>。</p><p>如果可用的內存和交換區大小都低於 10%，Early OOM 將會自動殺死最大的進程，直到系統有足夠的內存可以流暢的運行。你也可以根據你的需求配置最小百分比值。</p><p>設置最小的可用內存百分比，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>earlyoom -m &lt;PERCENT_HERE&gt;</span></span></code></pre></div><p>設置最小可用交換區百分比, 運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>earlyoom -s &lt;PERCENT_HERE&gt;</span></span></code></pre></div><p>在幫助部分，可以看到更多詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ earlyoom -h</span></span>
<span class="line"><span>earlyoom 0.12</span></span>
<span class="line"><span>Usage: earlyoom [OPTION]...</span></span>
<span class="line"><span></span></span>
<span class="line"><span> -m PERCENT set available memory minimum to PERCENT of total (default 10 %)</span></span>
<span class="line"><span> -s PERCENT set free swap minimum to PERCENT of total (default 10 %)</span></span>
<span class="line"><span> -M SIZE set available memory minimum to SIZE KiB</span></span>
<span class="line"><span> -S SIZE set free swap minimum to SIZE KiB</span></span>
<span class="line"><span> -k use kernel oom killer instead of own user-space implementation</span></span>
<span class="line"><span> -i user-space oom killer should ignore positive oom_score_adj values</span></span>
<span class="line"><span> -d enable debugging messages</span></span>
<span class="line"><span> -v print version information and exit</span></span>
<span class="line"><span> -r INTERVAL memory report interval in seconds (default 1), set to 0 to</span></span>
<span class="line"><span> disable completely</span></span>
<span class="line"><span> -p set niceness of earlyoom to -20 and oom_score_adj to -1000</span></span>
<span class="line"><span> -h this help text</span></span></code></pre></div><p>現在，你再也不用擔心內存消耗最高的進程了。希望這能給你幫助。更多的好內容將會到來，敬請期待。</p><p>謝謝！</p><hr>`,23)),l("p",null,[s[10]||(s[10]=a("via: ",-1)),n(e,{href:"https://www.ostechnix.com/kill-largest-process-unresponsive-linux-system/"},{default:i(()=>[...s[9]||(s[9]=[a("https://www.ostechnix.com/kill-largest-process-unresponsive-linux-system/",-1)])]),_:1})]),l("p",null,[s[14]||(s[14]=a("作者：",-1)),n(e,{href:"https://www.ostechnix.com"},{default:i(()=>[...s[11]||(s[11]=[a("Aditya Goturu",-1)])]),_:1}),s[15]||(s[15]=a(" 譯者：",-1)),n(e,{href:"https://github.com/cizezsy"},{default:i(()=>[...s[12]||(s[12]=[a("cizezsy",-1)])]),_:1}),s[16]||(s[16]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[19]||(s[19]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[18]||(s[18]=[a("Linux中國",-1)])]),_:1}),s[21]||(s[21]=a(" 榮譽推出",-1))])])}const T=p(h,[["render",g]]);export{x as __pageData,T as default};
